import * as CollapsiblePrimitive from "@radix-ui/react-collapsible";
import { ChevronDown } from "lucide-react";
import type { ComponentProps } from "react";
import { ToolCall, type ToolCallProps, type ToolCallStatus } from "./tool-call";
import { cn } from "./utils";

type ToolCallGroupCall = ToolCallProps & { id: string };

type ToolCallGroupProps = Omit<
    ComponentProps<"section">,
    "aria-label" | "children"
> & {
    id: string;
    name: string;
    calls: readonly ToolCallGroupCall[];
    variant?: "panel" | "compact";
    open?: boolean;
    defaultOpen?: boolean;
    onOpenChange?: (open: boolean) => void;
    loading?: boolean;
};

const statusLabels: Record<ToolCallStatus, string> = {
    pending: "대기",
    running: "실행 중",
    succeeded: "완료",
    failed: "실패",
    "awaiting-approval": "승인 대기",
    denied: "거부됨",
    cancelled: "취소됨",
};

const statusPriority: readonly ToolCallStatus[] = [
    "failed",
    "awaiting-approval",
    "running",
    "pending",
    "denied",
    "cancelled",
    "succeeded",
];

function isReadonlyArrayOf<T>(value: unknown): value is readonly T[] {
    return Array.isArray(value);
}

function aggregateStatus(calls: readonly ToolCallGroupCall[]) {
    const statuses = new Set(calls.map((call) => call.status));
    return statusPriority.find((status) => statuses.has(status));
}

function ToolCallGroup({
    id,
    name,
    calls,
    variant = "panel",
    open,
    defaultOpen = true,
    onOpenChange,
    loading = false,
    className,
    ...props
}: ToolCallGroupProps) {
    if (typeof id !== "string" || !id.trim() ||
        typeof name !== "string" || !name.trim()) {
        throw new Error("ToolCallGroup requires an ID and name.");
    }
    if (variant !== "panel" && variant !== "compact") {
        throw new Error("ToolCallGroup has an unsupported variant.");
    }

    if (!isReadonlyArrayOf<ToolCallGroupCall>(calls)) {
        throw new Error("ToolCallGroup calls must be an array.");
    }
    const ids = new Set<string>();
    for (const call of calls) {
        if (!call || typeof call.id !== "string" || !call.id.trim() ||
            ids.has(call.id)) {
            throw new Error("ToolCallGroup calls need unique IDs.");
        }
        ids.add(call.id);
    }

    const status = aggregateStatus(calls);
    const countLabel = `${calls.length}개`;

    return (
        <section id={id} aria-label={`도구 호출 그룹: ${name}`} data-ui="tool-call-group"
            data-group-id={id} data-variant={variant}
            data-status={status}
            data-surface={variant === "panel" ? "panel" : undefined}
            className={cn(
                "min-w-0 text-sm text-foreground",
                variant === "panel"
                    ? "rounded-sm border border-border bg-surface " +
                        "p-[var(--space-3)]"
                    : "min-w-0",
                className,
            )} {...props}>
            <CollapsiblePrimitive.Root open={open} defaultOpen={defaultOpen}
                onOpenChange={onOpenChange}>
                <span role="status" aria-live="polite" className="sr-only">
                    {name}: {loading ? "불러오는 중" :
                        status ? statusLabels[status] : "비어 있음"}
                </span>
                <CollapsiblePrimitive.Trigger
                    className={cn(
                        "group flex min-h-[var(--control-height)] w-full " +
                        "items-center justify-between gap-2 rounded-sm " +
                        "text-left focus-visible:outline-2 " +
                        "focus-visible:outline-focus",
                        variant === "panel" && "px-[var(--space-1)]",
                    )}>
                    <span data-slot={variant === "panel"
                        ? "surface-header" : undefined}
                        className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                        <strong data-slot="surface-title"
                            className="min-w-0 break-words font-semibold">
                            {name}
                        </strong>
                        <span className="shrink-0 text-xs text-muted">
                            {countLabel}
                        </span>
                        <span className={cn(
                            "shrink-0 text-xs",
                            status === "failed" || status === "denied"
                                ? "text-danger"
                                : status === "succeeded" ||
                                    status === "running" ||
                                    status === "awaiting-approval"
                                    ? "text-accent" : "text-muted",
                        )}>
                            {loading ? "불러오는 중" :
                                status ? statusLabels[status] : "비어 있음"}
                        </span>
                    </span>
                    <ChevronDown aria-hidden="true" className={cn(
                        "size-4 shrink-0 transition-transform " +
                        "duration-[var(--motion-fast)]",
                        "group-data-[state=open]:rotate-180",
                    )} />
                </CollapsiblePrimitive.Trigger>
                <CollapsiblePrimitive.Content className={cn(
                    "overflow-hidden",
                    variant === "panel" && "px-[var(--space-1)]",
                )}>
                    {calls.length > 0 ? (
                        <ul aria-label={`${name} 도구 호출 목록`}
                            className="m-0 grid list-none gap-2 p-0">
                            {calls.map(({ id: callId, ...call }) => (
                                <li key={callId} className="min-w-0">
                                    <ToolCall {...call} id={callId}
                                        variant="compact" />
                                </li>
                            ))}
                        </ul>
                    ) : (
                        <p role="status" className={cn(
                            "m-0 py-[var(--space-2)] text-sm text-muted",
                        )}>
                            {loading
                                ? "도구 호출을 불러오는 중입니다."
                                : "표시할 도구 호출이 없습니다."}
                        </p>
                    )}
                    {calls.length > 0 && loading && (
                        <p role="status" className="m-0 pt-2 text-xs text-muted">
                            추가 도구 호출을 불러오는 중입니다.
                        </p>
                    )}
                </CollapsiblePrimitive.Content>
            </CollapsiblePrimitive.Root>
        </section>
    );
}

export { ToolCallGroup };
export type { ToolCallGroupCall, ToolCallGroupProps };
